import {initWizard,goToStep,extraResources,normalizeResource} from './wizard.mjs';
initWizard();
import {initFunding,renderFunding,fundingData} from './funding.mjs';
initFunding();
import {calculate} from './finance.mjs';
import {businesses,assess,alternatives,matches} from './advisor.mjs';
const $=id=>document.getElementById(id),money=n=>new Intl.NumberFormat('en-IN',{style:'currency',currency:'INR',maximumFractionDigits:0}).format(n);
const escape=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const names={land:'land / open space',shop:'shop / spare room',water:'reliable water',kitchen:'kitchen & utensils',livestock:'milk-producing livestock',machine:'sewing machine',vehicle:'vehicle',phone:'smartphone',storage:'storage / cold room',tools:'tools / equipment',labor:'workers / family help',machine_mill:'flour-milling machine'};
let currentIdea=businesses[0].title,activeBusiness=businesses[0],verifiedLocation=null,inputs=null,result=null,marketData=null,scanSequence=0,lastAssessment=null,planResources=null,planGoal='';
const getResources=()=>({capital:Number($('capital').value),skill:$('skill').value,assets:[...new Set([...document.querySelectorAll('[name=asset]:checked')].map(x=>x.value).concat(extraResources().map(x=>x.key)))],items:extraResources()});
planResources=getResources();
for(const x of extraResources())if(!names[x.key])names[x.key]=x.name;
const allChoices=[...businesses,{id:'custom',title:'Custom business / my own idea'}];
$('intended').replaceChildren(...allChoices.map(b=>{const o=document.createElement('option');o.value=b.id;o.textContent=b.title;return o;}));
function loadBusinessExample(b){currentIdea=b.title;$('setup-cost').value=b.cost;$('own-money').value=planResources.capital;for(const key of ['price','variable','fixed','units'])$('finance').elements[key].value=b[key];$('finance').elements.principal.value=Math.max(0,b.cost-planResources.capital);$('demand').value='';$('known-competitors').value='';$('evidence-notes').value='';}
function numberOrUnknown(id){const v=$(id).value.trim();return v===''?null:Number(v);}
function renderAssessment(){if(!inputs||!planResources)return;const b=activeBusiness,resources=planResources;const mapped=marketData&&b.tags.length?marketData.elements.filter(x=>matches(b,x.tags)):null;const known=numberOrUnknown('known-competitors'),demand=numberOrUnknown('demand');lastAssessment=assess({business:b,resources,economics:inputs,knownCompetitors:known,demand,mappedCount:mapped?.length??null});const a=lastAssessment;
$('market-business').textContent=b.title;$('market-location').textContent=verifiedLocation?`${verifiedLocation.office}, ${verifiedLocation.district}, ${verifiedLocation.state} · PIN ${verifiedLocation.pin}${verifiedLocation.lat?'':' · map coordinates unavailable'}`:'Verify a PIN code above to search nearby mapped businesses.';
$('verdict').className='verdict'+(a.status==='Rework before investing'?' caution':'');$('verdict').innerHTML=`<span class="status-chip">${escape(a.status==='Rework before investing'?'Check before spending':a.status==='More evidence needed'?'Find out a little more':'Try a small start')}</span><h3>${escape(b.title)}</h3><p class="muted">${planGoal?escape(planGoal):'Assessment of your intended business using your submitted resources and current planner assumptions.'}</p><ul>${a.reasons.map(x=>`<li>${escape(x)}</li>`).join('')}</ul><div class="evidence-pills"><span>Mapped signals: ${mapped===null?'not assessed':mapped.length}</span><span>Your competitor count: ${known??'unknown'}</span><span>Your obtainable sales: ${demand??'unknown'}</span></div><h4>Your resource fit</h4>${resources.items?.length?'<p class="muted">Your items: '+resources.items.map(x=>escape(x.name)+' ('+escape(x.quantity)+')').join(', ')+'. Quantities are recorded; check that they are enough for the size of your business.</p>':''}<ul><li>Reuse: ${a.fit.reused.map(x=>escape(names[x]||x.replace('custom:',''))).join(', ')||'No required resource selected'}.</li><li>Missing: ${a.fit.missing.map(x=>escape(names[x]||x.replace('custom:',''))).join(', ')||'None of the listed core assets'}.</li><li>Skill match: ${a.fit.skillMatch?'yes':'training / experience needed'}. ${b.id==='custom'?'Custom startup cost is not estimated. Enter loan needs in step 4 after getting quotes.':'Illustrative investment gap: '+money(a.fit.gap)+'.'}</li></ul><h4>What to check next</h4><ul>${a.tasks.map(x=>`<li>${escape(x)}</li>`).join('')}</ul><p class="muted">This is an explainable screening rule, not a prediction of business growth. Five or more similar-business signals trigger a competition caution; customer demand and capacity still need field validation. Your count and mapped count are compared using the larger value, never added, to avoid double-counting.</p>`;
$('assumption-summary').textContent=`Price ${money(inputs.price)}/unit · variable cost ${money(inputs.variable)}/unit · fixed cost ${money(inputs.fixed)}/month. These editable assumptions determine break-even.`;
const ranked=alternatives(b,resources);$('alternatives-context').textContent=a.status==='Rework before investing'?'Your intended idea has caution flags. Compare these ways to reuse your resources before committing more money. Each alternative still needs its own demand check.':'Explore these other uses of the same resources. Resource fit alone does not show that an alternative has a better market.';
$('ideas').replaceChildren(...ranked.map((x,i)=>{const el=document.createElement('article');el.className='idea';el.innerHTML=`<div class="idea-top"><span>RESOURCE-REUSE OPTION</span><span>0${i+1} ↗</span></div><h3>${escape(x.title)}</h3><p>${escape(x.why)}</p><p class="resource-line"><b>Reuse:</b> ${x.fit.reused.map(k=>escape(names[k]||k.replace('custom:',''))).join(', ')}.</p><p><b>Missing:</b> ${x.fit.missing.map(k=>escape(names[k]||k.replace('custom:',''))).join(', ')||'None of the listed core assets'}.</p><p><b>Skill:</b> ${x.fit.skillMatch?'matches your selected skill':'training needed'}.</p><p><b>Illustrative setup:</b> ${money(x.cost)} · additional investment ${money(x.fit.gap)}.</p><p><b>Market:</b> ${marketData&&x.tags.length?marketData.elements.filter(e=>matches(x,e.tags)).length+' mapped similar-business signals. Demand not verified.':'Not assessed. Validate demand before investing.'}</p><p>${escape(x.check)}</p><button type="button">Assess this alternative instead →</button>`;el.querySelector('button').onclick=()=>{activeBusiness=x;$('intended').value=x.id;loadBusinessExample(x);renderFinance();goToStep(3);};return el;}));if(!ranked.length)$('ideas').innerHTML='<div class="empty-ideas">No alternative in this catalog reuses your selected assets. Add resources you actually own or consider acquiring a suitable asset; we will not label an unrelated business as a same-resource alternative.</div>';
}
$('assessment').onsubmit=e=>{e.preventDefault();planResources=getResources();for(const x of planResources.items)if(!names[x.key])names[x.key]=x.name;planGoal=$('business-goal').value.trim();if($('intended').value==='custom'){const assets=$('custom-required').value.split(',').map(x=>x.trim()).filter(Boolean).map(x=>{const key=normalizeResource(x);if(!names[key])names[key]=x;return key;});activeBusiness={id:'custom',title:$('custom-business-name').value.trim()||'My business idea',skill:planResources.skill,assets:[...new Set(assets)],cost:planResources.capital,price:100,variable:60,fixed:5000,units:150,tags:[],why:planGoal,check:'Get local setup-cost quotes, check any licenses and speak to buyers. Custom costs and sales are placeholders to replace in step 4.'};}else activeBusiness=businesses.find(x=>x.id===$('intended').value);loadBusinessExample(activeBusiness);renderFinance();goToStep(3);};
function renderFinance(){if(!$('finance').checkValidity())return;try{inputs=Object.fromEntries(new FormData($('finance')));for(const k in inputs)inputs[k]=Number(inputs[k]);result=calculate(inputs);const r=result;const metrics=[['Estimated monthly EMI',money(r.emi),`Total repayment ${money(r.total)}<br>Total interest ${money(r.interest)}`],['Break-even sales',r.breakEven===null?'No break-even':r.breakEven.toLocaleString('en-IN')+' units','Per month · operating costs only, excludes EMI'],['Operating profit',money(r.operating),'Per month · before EMI and tax'],['Cash after EMI',money(r.cash),'Per month · business operating profit minus EMI'],['Household buffer',money(r.buffer),'Existing income less expenses and all EMIs']];$('results').innerHTML=metrics.map(([label,value,note])=>`<div class="metric"><div><small>${label}</small><b>${value}</b></div><p>${note}</p></div>`).join('');renderScenario();renderAssessment();renderFunding(inputs,result);}catch(e){$('results').textContent=e.message;}}
function renderScenario(){if(!inputs)return;const change=Number($('scenario').value);$('scenario-label').textContent=change===0?'Base case':`${change>0?'+':''}${change}% sales`;const units=Math.round(inputs.units*(1+change/100));const s=calculate({...inputs,units});$('scenario-result').textContent=`At ${units.toLocaleString('en-IN')} units per month: revenue ${money(s.revenue)}, operating profit ${money(s.operating)}, cash after EMI ${money(s.cash)}. Price and costs per unit stay unchanged.`;}
$('finance').onsubmit=e=>{e.preventDefault();renderFinance();};$('scenario').oninput=renderScenario;renderFinance();
let offices=[],lookupSeq=0;
async function fetchJSON(url){const response=await fetch(url,{signal:AbortSignal.timeout(15000)});if(!response.ok)throw Error('Service unavailable');return response.json();}
$('pin-form').onsubmit=async e=>{e.preventDefault();const pin=$('pincode').value;if(!/^[1-9]\d{5}$/.test(pin))return;const seq=++lookupSeq;verifiedLocation=null;offices=[];$('office-label').hidden=true;$('map-caption').textContent='Map location has not been verified for the entered PIN.';$('pin-status').textContent='Checking postal records…';try{const data=await fetchJSON(`https://api.postalpincode.in/pincode/${encodeURIComponent(pin)}`);if(seq!==lookupSeq)return;offices=data?.[0]?.PostOffice||[];if(data?.[0]?.Status!=='Success'||!offices.length){$('pin-status').textContent='No postal record found for this PIN. Check the number and try again.';return;}$('office').replaceChildren(...offices.map((x,i)=>{const opt=document.createElement('option');opt.value=i;opt.textContent=`${x.Name} · ${x.District}, ${x.State}`;return opt;}));$('office-label').hidden=false;$('pin-status').textContent=`PIN ${pin} found · ${offices.length} postal location(s). Select your post office.`;await showOffice(pin,seq);}catch{$('pin-status').textContent='Postal lookup is unavailable. The PIN has not been verified; please retry later.';}};
async function showOffice(pin,seq){const office=offices[Number($('office').value)];if(!office)return;marketData=null;scanSequence++;verifiedLocation={pin,office:office.Name,district:office.District,state:office.State};$('mapped-businesses').replaceChildren();$('scan-status').textContent='Location changed. Run a new market check.';renderAssessment();$('map-caption').textContent=`${office.Name}, ${office.District} · postal record verified, locating map…`;try{const q=`${office.Name}, ${office.District}, ${office.State}, India`;const results=await fetchJSON(`https://nominatim.openstreetmap.org/search?format=json&limit=1&countrycodes=in&q=${encodeURIComponent(q)}`);if(seq!==lookupSeq||verifiedLocation?.office!==office.Name)return;if(!results.length)throw Error();const lat=Number(results[0].lat),lon=Number(results[0].lon);if(!Number.isFinite(lat)||!Number.isFinite(lon))throw Error();verifiedLocation.lat=lat;verifiedLocation.lon=lon;renderAssessment();$('map').src=`map.html?lat=${lat}&lon=${lon}&z=13`;$('map-link').href=`https://www.openstreetmap.org/?mlat=${lat}&mlon=${lon}#map=13/${lat}/${lon}`;$('map-caption').textContent=`${office.Name}, ${office.District}, ${office.State} · approximate locality`;}catch{if(seq===lookupSeq){$('map-caption').textContent='Postal record verified. Map positioning unavailable; the displayed map has not moved.';$('map-link').href=`https://www.openstreetmap.org/search?query=${encodeURIComponent(office.Name+', '+office.District+', '+office.State+', India')}`;}}}
$('office').onchange=()=>showOffice(verifiedLocation?.pin||$('pincode').value,++lookupSeq);
$('pincode').oninput=()=>{lookupSeq++;scanSequence++;marketData=null;verifiedLocation=null;$('mapped-businesses').replaceChildren();$('scan-status').textContent='Location changed; no current market data.';renderAssessment();$('office-label').hidden=true;$('pin-status').textContent='Enter a PIN code and select Find to verify it.';$('map-caption').textContent='Previous map view · current PIN not verified';};
$('save-plan').onclick=()=>{if(!$('finance').reportValidity())return;renderFinance();const text=`GRAMEEN ADVISOR — PERSONAL PLANNING WORKSHEET\n${new Date().toISOString().slice(0,10)}\n\nIdea: ${currentIdea||'Custom assumptions'}\nGoal: ${planGoal}\nSubmitted resources: ${JSON.stringify(planResources)}\nAssessment: ${JSON.stringify(lastAssessment)}\nYour market notes: ${$('evidence-notes').value}\nMapped evidence: ${marketData?JSON.stringify({checkedAt:marketData.checkedAt,source:'OpenStreetMap / Overpass',radiusMetres:3000,objectCount:marketData.elements.length}):'Not assessed'}\nLocation: ${verifiedLocation?JSON.stringify(verifiedLocation):'Not verified'}\n\nINPUTS (INR; monthly except annual rate and loan tenure)\n${JSON.stringify(inputs,null,2)}\n\nCALCULATED RESULTS\n${JSON.stringify(result,null,2)}\n\nFUNDING AND INSTALMENT SCHEDULE\n${JSON.stringify(fundingData(inputs),null,2)}\n\nNo break-even is possible when price does not exceed variable cost. Taxes, fees, depreciation and working-capital changes excluded. Household buffer uses existing household income only. Not an income guarantee or credit approval.\n`;const url=URL.createObjectURL(new Blob([text],{type:'text/plain'}));const a=document.createElement('a');a.href=url;a.download='Grameen_Advisor_Plan.txt';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};

$('market-evidence').onsubmit=e=>{e.preventDefault();if($('demand').value.trim()!=='')$('finance').elements.units.value=$('demand').value;renderFinance();};
$('scan-market').onclick=async()=>{
 if(!verifiedLocation?.lat||!verifiedLocation?.lon){$('scan-status').textContent='First verify a PIN code and select a post office with available map coordinates.';$('location').scrollIntoView({behavior:'smooth'});return;}
 const seq=++scanSequence,button=$('scan-market');button.disabled=true;marketData=null;$('mapped-businesses').replaceChildren();$('scan-status').textContent='Checking OpenStreetMap business entries within 3 km…';renderAssessment();
 const {lat,lon}=verifiedLocation;
 const pairs=[...new Map(businesses.flatMap(b=>b.tags).map(t=>[t.join('='),t])).values()];
 const query=`[out:json][timeout:20];(${pairs.map(([k,v])=>`nwr["${k}"="${v}"](around:3000,${lat},${lon});`).join('')});out center tags;`;
 try{const response=await fetch('https://overpass-api.de/api/interpreter',{method:'POST',headers:{'Content-Type':'application/x-www-form-urlencoded'},body:new URLSearchParams({data:query}),signal:AbortSignal.timeout(30000)});if(!response.ok)throw Error();const data=await response.json();if(seq!==scanSequence)return;if(!Array.isArray(data.elements)||data.remark)throw Error();
 marketData={elements:data.elements,checkedAt:new Date().toISOString()};$('scan-status').textContent=`Found ${data.elements.length} mapped objects across supported business categories within 3 km. Checked ${new Date().toLocaleString()}. Counts can include duplicate map representations and miss unmapped businesses. No results do not mean no competition.`;
 $('mapped-businesses').replaceChildren(...data.elements.slice(0,20).map(e=>{const div=document.createElement('div');div.className='mapped-item';const span=document.createElement('span');span.textContent=e.tags?.name||'Unnamed mapped business';const a=document.createElement('a');a.textContent='View record ↗';a.target='_blank';a.rel='noopener';if(['node','way','relation'].includes(e.type)&&Number.isInteger(e.id))a.href=`https://www.openstreetmap.org/${e.type}/${e.id}`;div.append(span,a);return div;}));renderAssessment();
 }catch{if(seq===scanSequence){marketData=null;$('scan-status').textContent='Live mapped-business lookup is unavailable. No competition count has been assumed. Add your own local observations and retry later.';renderAssessment();}}finally{button.disabled=false;}
};
